Q: SSAS &amp; SCD2 - how to deal with IsActive row in Dim A: <pre><code>
    def _save_refined_data(
        self,
        conn: duckdb.DuckDBPyConnection,
        table_name: str,
        settings: dict,
        table_config: TableConfig,
        timestamp: datetime
    ) -&gt; None:
        &quot;&quot;&quot;
        Sauvegarde les données REFINED en utilisant DuckDB.

        Args:
            conn: Connexion DuckDB
            table_name: Nom de la table DuckDB à sauvegarder
            settings: Configuration
            table_config: Configuration table
            timestamp: Timestamp
        &quot;&quot;&quot;
        refined_base_path = settings['paths']['refined']
        table_name_str = table_config.table_name

        # Créer répertoires
        current_dir = os.path.join(refined_base_path, table_name_str, 'current')
        os.makedirs(current_dir, exist_ok=True)

        # Purger current/ pour ne garder qu'un seul fichier (idempotence)
        # Supprimer tous les fichiers parquet existants dans current/
        purge_enabled = settings.get('idempotency', {}).get('purge_current_on_write', True)
        if purge_enabled:
            import glob
            existing_files = glob.glob(os.path.join(current_dir, f&quot;{table_name_str}-*.parquet&quot;))
            for old_file in existing_files:
                try:
                    os.remove(old_file)
                    self.logger.debug(f&quot;Purged old current file: {old_file}&quot;)
                except Exception as e:
                    self.logger.warning(f&quot;Could not remove old current file {old_file}: {e}&quot;)

        # Créer répertoire historique avec timestamp
        date_path = timestamp.strftime(&quot;%Y/%m/%d/%H/%M&quot;)
        history_dir = os.path.join(refined_base_path, table_name_str, date_path)
        os.makedirs(history_dir, exist_ok=True)

        # Format fichiers: {table_name}-YYYYMMDDTHHmm.parquet
        file_timestamp = timestamp.strftime(&quot;%Y%m%dT%H%M&quot;)
        filename = f&quot;{table_name_str}-{file_timestamp}.parquet&quot;

        # Sauvegarder version current (toutes les lignes actives)
        current_file_path = os.path.join(current_dir, filename)
        conn.execute(f&quot;&quot;&quot;
            COPY (
                SELECT * FROM {table_name}
                WHERE SCD_IS_CURRENT = TRUE
            ) TO '{current_file_path}' (FORMAT PARQUET, COMPRESSION zstd)
        &quot;&quot;&quot;)
        self.logger.info(f&quot;Saved CURRENT data to: {current_file_path}&quot;)

        # Sauvegarder version historique complète
        history_file_path = os.path.join(history_dir, filename)
        DuckDBUtils.write_table_to_parquet_static(conn, table_name, history_file_path)
        self.logger.info(f&quot;Saved HISTORY data to: {history_file_path}&quot;)

    def _load_enrichment_config(self) -&gt; dict:
        &quot;&quot;&quot;Charge la configuration d'enrichissement depuis enrichment.yaml.&quot;&quot;&quot;
        config_path = (
            Path(__file__).resolve().parents[2]
            / &quot;config&quot; / &quot;refined_config&quot; / &quot;enrichment.yaml&quot;
        )
        if not config_path.exists():
            return {}
        import yaml
        with open(config_path, 'r') as f:
            return yaml.safe_load(f) or {}

    def _apply_enrichment_columns(
        self,
        conn: duckdb.DuckDBPyConnection,
        table_name: str,
        settings: dict
    ) -&gt; None:
        &quot;&quot;&quot;
        Applique les colonnes d'enrichissement (lookup) à la table 'result'.

        Lit la config enrichment.yaml et pour chaque colonne définie,
        récupère la valeur depuis la table source REFINED et l'ajoute
        à toutes les lignes de 'result'.
        &quot;&quot;&quot;
        config = self._load_enrichment_config()
        enrichment_columns = config.get('enrichment_columns', {})

        if not enrichment_columns:
            return

        for col_name, col_def in enrichment_columns.items():
            # Vérifier exclusion
            if table_name in col_def.get('exclude', []):
                self.logger.debug(
                    f&quot;Skipping enrichment {col_name} for excluded table {table_name}&quot;
                )
                continue

            apply_to = col_def.get('apply_to', 'all')
            if apply_to != 'all' and table_name not in apply_to:
                continue

            # Résoudre le parquet RAW source
            source_table = col_def['source_table']
            target_column = col_def.get('target_column', col_name)
            value_col = col_def['value_column']

            # Support single filter (dict) or multiple filters (list)
            raw_filter = col_def['filter']
            if isinstance(raw_filter, dict):
                filters = [raw_filter]
            else:
                filters = raw_filter

            # Look in RAW layer (recursive search in date-partitioned dirs)
            raw_base = os.path.join(
                settings['paths']['raw'], source_table
            )
            source_file = None
            raw_path = Path(raw_base)
            if raw_path.exists():
                parquet_files = list(raw_path.rglob(f&quot;{source_table}-*.parquet&quot;))
                if parquet_files:
                    source_file = str(max(parquet_files, key=lambda f: f.stat().st_mtime))

            if not source_file:
                self.logger.warning(
                    f&quot;Enrichment source {source_table} not found, &quot;
                    f&quot;{target_column} will be NULL&quot;
                )
                conn.execute(
                    f'CREATE OR REPLACE TABLE result AS '
                    f'SELECT *, NULL::VARCHAR AS &quot;{target_column}&quot; FROM result'
                )
                continue

            # Build WHERE clause from filters
            where_parts = []
            for f in filters:
                f_col = f['column']
                f_val = f['value']
                where_parts.append(
                    f&quot;CAST(\&quot;{f_col}\&quot; AS VARCHAR) = '{f_val}'&quot;
                )
            where_clause = ' AND '.join(where_parts)
            filter_desc = ', '.join(
                f&quot;{f['column']}='{f['value']}'&quot; for f in filters
            )

            # Lookup DuckDB
            try:
                lookup = conn.execute(f&quot;&quot;&quot;
                    SELECT &quot;{value_col}&quot;
                    FROM read_parquet('{source_file}')
                    WHERE {where_clause}
                    LIMIT 1
                &quot;&quot;&quot;).fetchone()

                if lookup and lookup[0] is not None:
                    value = str(lookup[0])
                    self.logger.info(
                        f&quot;Enrichment: {target_column} = '{value}' &quot;
                        f&quot;(from {source_table})&quot;
                    )
                    conn.execute(
                        f&quot;CREATE OR REPLACE TABLE result AS &quot;
                        f&quot;SELECT *, '{value}' AS \&quot;{target_column}\&quot; FROM result&quot;
                    )
                else:
                    self.logger.warning(
                        f&quot;No value in {source_table} for &quot;
                        f&quot;{filter_desc}, {target_column} = NULL&quot;
                    )
                    conn.execute(
                        f'CREATE OR REPLACE TABLE result AS '
                        f'SELECT *, NULL::VARCHAR AS &quot;{target_column}&quot; FROM result'
                    )
            except Exception as e:
                self.logger.error(f&quot;Enrichment error for {target_column}: {e}&quot;)

    def _sanitize_column_names(
        self,
        conn: 'duckdb.DuckDBPyConnection',
        table_name: str,
    ) -&gt; None:
        &quot;&quot;&quot;
        Nettoie les noms de colonnes d'une table DuckDB pour qu'ils respectent
        le pattern SQL identifier strict (`^[A-Za-z][A-Za-z0-9_]*$`).

        Supprime :
        - BOM UTF-8 (`\\ufeff`) en début ou fin de nom
        - Espaces / tabs / newlines / autres whitespace
        - Caractères de contrôle non imprimables
        - Tout caractère qui n'est ni lettre ASCII, ni chiffre, ni underscore

        Si après nettoyage le nom est différent de l'original, on fait un
        `ALTER TABLE ... RENAME COLUMN` dans DuckDB. Si plusieurs colonnes
        nettoyées finissent avec le même nom (collision), une SecurityError
        est levée — c'est un cas pathologique que l'opérateur doit fixer
        à la main dans le YAML / le CSV source.

        Cette méthode est défensive : si tout est déjà propre, elle ne fait
        rien (zéro overhead).
        &quot;&quot;&quot;
        import re

        actual_cols = [
            row[0] for row in conn.execute(f&quot;DESCRIBE {table_name}&quot;).fetchall()
        ]

        # Set des colonnes intactes (qui ne changeront pas) — utile pour
        # détecter une collision avec une colonne déjà propre
        unchanged_cols: set = set()
        # Map original → cleaned (uniquement les colonnes qui changent)
        rename_map: Dict[str, str] = {}
        cleaned_seen: Dict[str, str] = {}  # cleaned_name → original (collision check)

        for original in actual_cols:
            # 1. Strip whitespace + BOM UTF-8 (\ufeff) début/fin
            cleaned = original.strip().lstrip('\ufeff').rstrip('\ufeff').strip()

            # 2. Supprimer tout caractère qui n'est pas [A-Za-z0-9_] au milieu
            cleaned = re.sub(r'[^A-Za-z0-9_]', '_', cleaned)

            # 3. Si commence par un chiffre, préfixer avec '_'
            if cleaned and cleaned[0].isdigit():
                cleaned = '_' + cleaned

            # 4. Vérifier qu'on a quelque chose à la fin
            if not cleaned:
                self.logger.error(
                    f&quot;Column {original!r} in {table_name} cannot be sanitized &quot;
                    f&quot;(empty after cleanup) — this column will be left as-is &quot;
                    f&quot;and will likely cause downstream errors.&quot;
                )
                continue

            if cleaned == original:
                unchanged_cols.add(cleaned)
                continue

            # Le nom va être renommé. Vérifier les collisions :
            # (a) avec une autre colonne déjà renommée vers le même nom
            if cleaned in cleaned_seen:
                raise ValueError(
                    f&quot;Column name collision after sanitization in &quot;
                    f&quot;{table_name}: {original!r} and {cleaned_seen[cleaned]!r} &quot;
                    f&quot;both clean to {cleaned!r}. Fix the source data or &quot;
                    f&quot;YAML data contract.&quot;
                )
            # (b) avec une colonne déjà propre qui porte ce nom
            if cleaned in actual_cols and cleaned != original:
                raise ValueError(
                    f&quot;Column name collision after sanitization in &quot;
                    f&quot;{table_name}: {original!r} would be renamed to {cleaned!r}, &quot;
                    f&quot;but a column with that name already exists. Fix the source &quot;
                    f&quot;data or YAML data contract.&quot;
                )

            cleaned_seen[cleaned] = original
            rename_map[original] = cleaned

        # Appliquer les renames
        for original, cleaned in rename_map.items():
            self.logger.warning(
                f&quot;Sanitizing column {original!r} → {cleaned!r} in {table_name} &quot;
                f&quot;(removed invisible/illegal characters)&quot;
            )
            # Escape les guillemets dans les noms originaux pour SQL
            original_sql = original.replace('&quot;', '&quot;&quot;')
            cleaned_sql = cleaned.replace('&quot;', '&quot;&quot;')
            conn.execute(
                f'ALTER TABLE {table_name} RENAME COLUMN &quot;{original_sql}&quot; TO &quot;{cleaned_sql}&quot;'
            )

        if rename_map:
            self.logger.info(
                f&quot;Sanitized {len(rename_map)} column name(s) in {table_name}&quot;
            )

    def _strip_enrichment_columns(
        self,
        conn: duckdb.DuckDBPyConnection,
        table_name: str
    ) -&gt; None:
        &quot;&quot;&quot;
        Supprime les colonnes d'enrichissement d'une table DuckDB.

        Nécessaire avant le merge SCD2 pour que current_data et raw_scd2
        aient le même nombre de colonnes (UNION ALL).
        &quot;&quot;&quot;
        config = self._load_enrichment_config()
        enrichment_columns = config.get('enrichment_columns', {})

        if not enrichment_columns:
            return

        # Colonnes présentes dans la table
        existing_cols = {
            col[0] for col in conn.execute(f&quot;DESCRIBE {table_name}&quot;).fetchall()
        }

        cols_to_drop = []
        for col_def in enrichment_columns.values():
            target_col = col_def.get('target_column', '')
            if target_col in existing_cols:
                cols_to_drop.append(target_col)

        if cols_to_drop:
            for col in cols_to_drop:
                conn.execute(f'ALTER TABLE {table_name} DROP COLUMN &quot;{col}&quot;')
            self.logger.debug(
                f&quot;Stripped enrichment columns {cols_to_drop} from {table_name}&quot;
            )
</code></pre>

Q: CodeIgniter&#39;s or_where() containing BETWEEN does not render a condition starting with OR A: <p>Your bug is most likely a problem that has been resolved in subsequent version releases of CodeIgniter. We don't know what version you were using, but I've never seen such a bug with CI3.</p>
<ol>
<li>I recommend avoiding d/m/Y (little-endian) format for date comparisons throughout an application. If you need to ensure that <code>$from</code> is less than <code>$to</code> in PHP, d/m/Y will not be reliable. Your table columns should be DATE type.</li>
<li>Your query only has one table, so it is not necessary to qualify columns with their table of origin.</li>
<li>When checking if a column contains a value from a whitelist, use an IN () expression.</li>
<li>To encapsulate WHERE condition logic with CodeIgniter's query builder methods, use <code>group_start()</code> and <code>group_end()</code>.</li>
<li>Because CodeIgniter implicitly disables escaping/quoting when a WHERE expression contains a parenthesis or single-quote, you can pass your pre-quoted BETWEEN expressions to <code>or_where()</code> without passing <code>false</code> as the &quot;$escape&quot; parameter.</li>
<li>Because your query doesn't use any aggregate functions, instead of using GROUP BY, you can just add DISTINCT to the SELECT clause.</li>
<li>If your query only returns one column from the database, it makes sense to flatten the result to be returned by the model method. Below will return a flat, indexed array of zero or more ids.</li>
<li>Pass the table name to the builder via the <code>get()</code> call which has to be called anyway to execute the query; this spares needing to call <code>from()</code>.</li>
</ol>
<pre class="lang-php prettyprint-override"><code>public function getStudentIds(
    ?string $fromYmd = null,
    ?string $toYmd = null
): array {
    if ($fromYmd &amp;&amp; $toYmd) {
        $btwn = vsprintf(
            'BETWEEN %s AND %s',
            $this-&gt;db-&gt;escape([$fromYmd, $toYmd])
        );
        $this-&gt;db
            -&gt;group_start()
            -&gt;or_where([
                &quot;ab_date $btwn&quot; =&gt; null,
                &quot;as_date $btwn&quot; =&gt; null
            ])
            -&gt;group_end();
    }

    return array_column(
        $this-&gt;db
            -&gt;distinct()
            -&gt;select('st_id')
            -&gt;where_in('st_status', [1, 2])
            -&gt;get('st_student')
            -&gt;result(),
        'st_id'
    );
}
</code></pre>

Q: Calculate multiple stats for two or more columns in R data.table A: <p>Make <code>stats()</code> return a flat list (no nesting) for all <code>.SDcols</code>.</p>
<pre class="lang-r prettyprint-override"><code>stats &lt;- function(DT) {
    lapply(DT, \(x) list(maximo = max(x), minimo = min(x))) |&gt;
        unlist(recursive = FALSE) # same as do.call(c, args = _)
}

dt[, stats(.SD), by = class, .SDcols = c('val1', 'val2')]

